//go:build ignore

// Generates docs/config-builder-templates.js from templates/*.yaml: every template in that
// folder becomes a selectable template in the Config Builder, so templates are added or
// removed by adding or removing a file. Run with `make builder-templates`;
// `go run scripts/gen_builder_templates.go -check` fails when the generated file is stale (CI).
//
// Header comments of a template file give its label and description:
//
//	# title: AI compact          (English; also the fallback)
//	# title.cs: AI kompaktní     (any other language of the site)
//	# description: one or more lines; continuation lines start with "#   "
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/heptau/pg_procrustes/config"
)

type template struct {
	Title       map[string]string `json:"title"`
	Description string            `json:"description"`
	Settings    map[string]string `json:"settings"`
}

func flatten(m map[string]any, prefix string, out map[string]string) {
	for k, v := range m {
		key := prefix + k
		switch t := v.(type) {
		case map[string]any:
			flatten(t, key+".", out)
		case []any:
			// lists (exceptions) are not options of the builder
		default:
			out[key] = fmt.Sprint(t)
		}
	}
}

func header(path string) (title map[string]string, desc string) {
	data, err := os.ReadFile(path)
	failIf(err)
	title = map[string]string{}
	inDesc := false
	for _, line := range strings.Split(string(data), "\n") {
		if !strings.HasPrefix(line, "#") {
			break
		}
		body := strings.TrimPrefix(line, "#")
		switch {
		case strings.HasPrefix(body, " title:"):
			title["en"] = strings.TrimSpace(strings.TrimPrefix(body, " title:"))
			inDesc = false
		case strings.HasPrefix(body, " title."):
			rest := strings.TrimPrefix(body, " title.")
			if i := strings.Index(rest, ":"); i > 0 {
				title[rest[:i]] = strings.TrimSpace(rest[i+1:])
			}
			inDesc = false
		case strings.HasPrefix(body, " description:"):
			desc = strings.TrimSpace(strings.TrimPrefix(body, " description:"))
			inDesc = true
		case inDesc && strings.HasPrefix(body, "   "):
			desc += " " + strings.TrimSpace(body)
		default:
			inDesc = false
		}
	}
	return title, desc
}

func main() {
	check := flag.Bool("check", false, "fail if docs/config-builder-templates.js is out of date")
	flag.Parse()

	files, _ := filepath.Glob("templates/*.yaml")
	sort.Strings(files)
	all := map[string]template{}
	var names []string
	for _, f := range files {
		name := strings.TrimSuffix(filepath.Base(f), ".yaml")
		merged, _, err := config.MergedSettings(f)
		failIf(err)
		settings := map[string]string{}
		flatten(merged, "", settings)
		title, desc := header(f)
		if title["en"] == "" {
			title["en"] = name
		}
		all[name] = template{Title: title, Description: desc, Settings: settings}
		names = append(names, name)
	}

	var buf bytes.Buffer
	buf.WriteString("// GENERATED by scripts/gen_builder_templates.go from templates/*.yaml — do not edit.\n")
	buf.WriteString("// Add or remove a file in templates/ and run `make builder-templates`.\nwindow.CB_PRESETS = {\n")
	for i, name := range names {
		b, err := json.MarshalIndent(all[name], "  ", "  ")
		failIf(err)
		key, _ := json.Marshal(name)
		fmt.Fprintf(&buf, "  %s: %s", key, b)
		if i < len(names)-1 {
			buf.WriteString(",")
		}
		buf.WriteString("\n")
	}
	buf.WriteString("};\n")

	const out = "docs/config-builder-templates.js"
	if *check {
		cur, _ := os.ReadFile(out)
		if !bytes.Equal(cur, buf.Bytes()) {
			fmt.Fprintf(os.Stderr, "%s is out of date: run `make builder-templates`\n", out)
			os.Exit(1)
		}
		return
	}
	failIf(os.WriteFile(out, buf.Bytes(), 0o644))
	fmt.Printf("wrote %s: %d templates\n", out, len(names))
}

func failIf(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
